## Code Example
```javascript
// Ring buffer with 64-bit sequence per slot
struct Slot {
    alignas(64) uint8_t data[64];
    std::atomic<uint64_t> seq;
};

class Ring {
    Slot buffer[N];
    std::atomic<uint64_t> head{0}, tail{0};

public:
    bool enqueue(const void* payload) {
        uint64_t pos = tail.fetch_add(1, std::memory_order_relaxed);
        uint64_t seq = buffer[pos & mask].seq.load(std::memory_order_acquire);
        if (seq != pos) return false; // full or wrap-around
        memcpy(buffer[pos & mask].data, payload, 64);
        buffer[pos & mask].seq.store(pos + 1, std::memory_order_release);
        return true;
    }

    bool dequeue(void* payload) {
        uint64_t pos = head.load(std::memory_order_relaxed);
        uint64_t seq = buffer[pos & mask].seq.load(std::memory_order_acquire);
        if (seq != pos + 1) return false; // empty
        memcpy(payload, buffer[pos & mask].data, 64);
        buffer[pos & mask].seq.store(pos + N + 1, std::memory_order_release);
        head.store(pos + 1, std::memory_order_relaxed);
        return true;
    }
};

// Two rings per priority, producer selects based on flag
```

